 order(M, 'Расположите шаги построения изображения в собирающей линзе.', ['Провести луч, параллельный оси, — после линзы через фокус', 'Провести луч через оптический центр без преломления', 'Найти точку пересечения лучей', 'Это изображение вершины предмета'], 'Построение двумя лучами.'),
 ch(M, 'Как изменится изображение, если закрыть половину собирающей линзы?', ['Станет менее ярким, но останется целым', 'Исчезнет половина изображения', 'Исчезнет полностью', 'Станет вдвое меньше'], 0, 'Каждая часть линзы строит всё изображение.'),
 num(M, 'Фокусное расстояние объектива {{F}} см. На каком расстоянии от объектива получится изображение очень далёкого предмета?', 'F', 'см', 'Для далёкого предмета $d \\to \\infty$, $f = F$.', [C('F', [5, 10, 50])]),
