 num(S, 'Две линзы {{D1}} и {{D2}} дптр вплотную. Найдите фокусное расстояние системы (см).', '100 / (D1 + D2)', 'см', '$D = D_1 + D_2$, $F = 1/D$.', [C('D1', [5, 8, 10]), C('D2', [-2, -3, 2])], decimals=1),
