 num(H, 'Близорукий человек ясно видит предметы на расстоянии не дальше {{d}} см. Какие очки нужны, чтобы видеть далёкие предметы (дптр)?', '-100 / d', 'дптр', 'Линза должна давать изображение бесконечно далёкого предмета на расстоянии $d$: $D = -1/d$.', [C('d', [20, 25, 40, 50])], decimals=1),
 multi(H, 'Выберите верные утверждения о системе двух линз вплотную.', ['Оптические силы складываются', 'Собирающая + рассеивающая равной силы дают $D = 0$', 'Система может быть рассеивающей', 'Фокусные расстояния складываются', 'Система всегда собирающая'], [0, 1, 2], '$D = D_1 + D_2$.'),
 num(H, 'Линза даёт действительное изображение с увеличением {{g1}}. Предмет передвинули на {{x}} см, и увеличение стало {{g2}} (тоже действительное). Найдите фокусное расстояние, если предмет отодвинули от линзы.', 'x / (1 / g2 - 1 / g1)', 'см', '$d = F\\left(1 + \\dfrac{1}{\\Gamma}\\right)$: $\\Delta d = F\\left(\\dfrac{1}{\\Gamma_2} - \\dfrac{1}{\\Gamma_1}\\right)$.', [C('g1', [2, 4]), C('g2', [0.5, 1]), C('x', [10, 15])], decimals=1),
 order(H, 'Расположите по возрастанию увеличение (собирающая линза F = 20 см), предмет на:', ['100 см', '60 см', '40 см', '30 см'], '0,25; 0,5; 1; 2.'),
 match(H, 'Установите соответствие: собирающая линза F = 10 см, предмет на d.', ['d = 15 см', 'd = 20 см', 'd = 30 см', 'd = 5 см'], ['f = 30 см, Γ = 2', 'f = 20 см, Γ = 1', 'f = 15 см, Γ = 0,5', 'мнимое, Γ = 2'], 'Формула линзы.'),
 cloze(H, 'Минимальное расстояние между предметом и его действительным изображением в собирающей линзе равно ___ фокусным расстояниям.', ['четырём', '4', 'четыре'], 'При $d = f = 2F$.'),
 num(H, 'С помощью линзы на экране получили изображение Солнца диаметром {{D}} мм. Угловой диаметр Солнца ≈ $9{,}3 \\cdot 10^{-3}$ рад. Найдите фокусное расстояние (см).', 'D / 0.0093 / 10', 'см', 'Изображение далёкого объекта в фокальной плоскости: $D_{изобр} = F\\theta$.', [C('D', [0.93, 1.86, 4.65])], decimals=0),
